import React, { useRef } from "react";

const Ref = () => {
  const myRef = useRef();
  console.log(myRef.current);
  return (
    <div>
      <input type="text" ref={myRef} />
      <p>Hello, {myRef.current && myRef.current.value}</p>
    </div>
  );
};

export default Ref;
